def on_trace_start(self, trace: Trace) -> None:
    """Called when a trace is started.

    Args:
        trace: The trace that started.
    """
    otel_span = self._tracer.start_span(
        name=trace.name,
        attributes={
            OPENINFERENCE_SPAN_KIND: OpenInferenceSpanKindValues.AGENT.value,
        },
    )
    self._root_spans[trace.trace_id] = otel_span
    self._trace_had_error[trace.trace_id] = False

def on_trace_end(self, trace: Trace) -> None:
    """Called when a trace is finished.

    Args:
        trace: The trace that started.
    """
    root_span = self._root_spans.pop(trace.trace_id, None)
    had_error = self._trace_had_error.pop(trace.trace_id, False)
    if root_span:
        if had_error:
            root_span.set_status(Status(StatusCode.ERROR))
        else:
            root_span.set_status(Status(StatusCode.OK))
        root_span.end()

